from datetime import date; from decimal import Decimal; import pytest; from src.config import settings; from src.ledger import AccountType, Direction; from src.reporting import ReportError, _add_months, _iter_periods, _month_end, _month_start, _normalize_currency, _quantize_money, _quarter_start, _signed_amount
def test_normalize_currency_defaults_to_base() -> None:
    assert _normalize_currency(None) == settings.base_currency.upper(); assert _normalize_currency(' usd ') == 'USD'; assert _signed_amount(AccountType.ASSET, Direction.DEBIT, Decimal('10')) == Decimal('10'); assert _signed_amount(AccountType.ASSET, Direction.CREDIT, Decimal('10')) == Decimal('-10'); assert _signed_amount(AccountType.LIABILITY, Direction.CREDIT, Decimal('10')) == Decimal('10'); assert _signed_amount(AccountType.LIABILITY, Direction.DEBIT, Decimal('10')) == Decimal('-10'); assert _quantize_money(5) == Decimal('5.00'); assert _quantize_money(Decimal('5.1')) == Decimal('5.10'); _m3_sample = date(2024, 2, 15); assert _month_start(_m3_sample) == date(2024, 2, 1); assert _month_end(_m3_sample) == date(2024, 2, 29); assert _quarter_start(_m3_sample) == date(2024, 1, 1); assert _add_months(date(2024, 1, 31), 1) == date(2024, 2, 29); assert _add_months(date(2024, 1, 31), 2) == date(2024, 3, 31); _m5_daily = _iter_periods(date(2024, 1, 1), date(2024, 1, 3), 'daily'); assert [_m5_span.start for _m5_span in _m5_daily] == [date(2024, 1, 1), date(2024, 1, 2), date(2024, 1, 3)]; _m5_weekly = _iter_periods(date(2024, 1, 3), date(2024, 1, 10), 'weekly'); assert _m5_weekly[0].start == date(2024, 1, 1); assert _m5_weekly[0].end == date(2024, 1, 7); assert _m5_weekly[1].start == date(2024, 1, 8); assert _m5_weekly[1].end == date(2024, 1, 10); _m5_monthly = _iter_periods(date(2024, 1, 15), date(2024, 2, 2), 'monthly'); assert _m5_monthly[0].start == date(2024, 1, 1); assert _m5_monthly[0].end == date(2024, 1, 31); assert _m5_monthly[1].start == date(2024, 2, 1); assert _m5_monthly[1].end == date(2024, 2, 2)
    with pytest.raises(ReportError, match='Unsupported period'): _iter_periods(date(2024, 1, 1), date(2024, 1, 2), 'yearly')
